{
  "title": "初入江湖",
  "scene": "你站在古城外的酒肆前，夕阳西下，古城的轮廓被染上了一层金黄。酒肆内传来阵阵谈笑声，几名江湖人正在谈笑风生。你穿着一身粗布衣裳，显得与周围的气氛格格不入。",
  "goal": "了解江湖的基本规则，赢得一杯酒。",
  "choices": [
    {
      "id": "A",
      "text": "上前与一名看起来武艺高强的江湖人搭话",
      "outcome": "你主动上前搭话，不卑不亢地询问此处的规矩。他看着你，眼中闪过一丝赞赏，随即分享了一些江湖基本规则，并邀请你品尝他手中的酒。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "装作若无其事地走过去，直接拿出酒钱要酒",
      "outcome": "你直接拿出酒钱要酒，但周围的江湖人显得十分惊讶，甚至有人开始低声议论。你显得有些手足无措，酒肆老板也不好意思地摇了摇头，表示不再给你酒。",
      "result": "fail",
      "next": "bad_end"
    },
    {
      "id": "C",
      "text": "站在远处观察，不愿主动上前"
      "outcome": "你选择站在远处观察，希望能够从别人的交流中学到一些东西。然而，这样做的效果不大，你并没有从旁观中学到什么。最终，你还是没能赢得酒。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
